def apply(inputs, premises):
    total = int(inputs["ticket_price"])
    carry_limits = sorted(inputs["carry_on_dimension_limits"])
    carry_used = False
    checked_count = 0
    for i in range(len(inputs["bag_weights"])):
        dims = sorted([inputs["bag_lengths"][i], inputs["bag_widths"][i], inputs["bag_heights"][i]])
        fits_carry = dims[0] <= carry_limits[0] and dims[1] <= carry_limits[1] and dims[2] <= carry_limits[2]
        if fits_carry and not carry_used:
            carry_used = True
        else:
            checked_count = checked_count + 1
            base_fee = inputs["fourth_plus_checked_fee"]
            if checked_count == 1:
                base_fee = inputs["first_checked_fee"]
            elif checked_count == 2:
                base_fee = inputs["second_checked_fee"]
            elif checked_count == 3:
                base_fee = inputs["third_checked_fee"]
            size_fee = 0
            linear_size = inputs["bag_lengths"][i] + inputs["bag_widths"][i] + inputs["bag_heights"][i]
            if linear_size > inputs["standard_checked_linear_size"]:
                for j in range(len(inputs["oversize_upper_bounds"])):
                    if linear_size <= inputs["oversize_upper_bounds"][j] and size_fee == 0:
                        size_fee = inputs["oversize_fees"][j]
            weight_fee = 0
            if inputs["bag_weights"][i] > inputs["standard_checked_weight"]:
                for j in range(len(inputs["overweight_upper_bounds"])):
                    if inputs["bag_weights"][i] <= inputs["overweight_upper_bounds"][j] and weight_fee == 0:
                        weight_fee = inputs["overweight_fees"][j]
            total = total + base_fee + max(size_fee, weight_fee)
    return {"answer": int(total)}

